<?php
session_start();
mysqli_report(MYSQLI_REPORT_OFF);
$host=getenv('MYSQLHOST')?:'localhost';
$port=(int)(getenv('MYSQLPORT')?:3306);
$user=getenv('MYSQLUSER')?:'root';
$pass=getenv('MYSQLPASSWORD')?:'';
$db=getenv('MYSQLDATABASE')?:'railway';
$conn=@new mysqli($host,$user,$pass,$db,$port);
if($conn->connect_errno){http_response_code(500);die('<h2 style="font-family:Arial;padding:40px">Database connection failed. Please try again shortly.</h2>');}
$conn->set_charset('utf8mb4');
$conn->query("CREATE TABLE IF NOT EXISTS users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$conn->query("CREATE TABLE IF NOT EXISTS cars(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,car_name VARCHAR(120) NOT NULL,brand VARCHAR(100) NOT NULL,model VARCHAR(120) NOT NULL,year SMALLINT UNSIGNED NOT NULL,color VARCHAR(60) NOT NULL,fuel_type ENUM('Petrol','Diesel','Electric','Hybrid','CNG','Other') NOT NULL DEFAULT 'Petrol',price DECIMAL(14,2) NOT NULL DEFAULT 0,image_data MEDIUMTEXT NULL,image_type VARCHAR(50) NULL,description TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id),INDEX(brand),INDEX(year),CONSTRAINT fk_cars_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function go($u){header('Location: '.$u);exit;}
function logged(){return !empty($_SESSION['user_id']);}
function guard(){if(!logged())go('?p=login');}
function flash($t,$m){$_SESSION['flash']=[$t,$m];}
function csrf(){return isset($_POST['csrf'],$_SESSION['csrf'])&&hash_equals($_SESSION['csrf'],$_POST['csrf']);}
function car($conn,$id,$uid){$s=$conn->prepare('SELECT * FROM cars WHERE id=? AND user_id=?');$s->bind_param('ii',$id,$uid);$s->execute();return $s->get_result()->fetch_assoc();}
function imageSrc($c){return !empty($c['image_data'])&&!empty($c['image_type'])?'data:'.e($c['image_type']).';base64,'.$c['image_data']:'';}
$p=$_GET['p']??'home';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!csrf()){flash('error','Your session expired. Please try again.');go('?p='.$p);}
 $a=$_POST['action']??'';
 if($a==='register'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pw=$_POST['password']??'';$cp=$_POST['confirm']??'';if(strlen($name)<2)$errors[]='Enter your full name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if(strlen($pw)<6)$errors[]='Password must be at least 6 characters.';if($pw!==$cp)$errors[]='Passwords do not match.';if(!$errors){$h=password_hash($pw,PASSWORD_DEFAULT);$s=$conn->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$s->bind_param('sss',$name,$email,$h);if($s->execute()){flash('success','Account created. Please log in.');go('?p=login');}$errors[]=$s->errno===1062?'This email is already registered.':'Could not create account.';}}
 if($a==='login'){$email=trim($_POST['email']??'');$pw=$_POST['password']??'';$s=$conn->prepare('SELECT id,name,email,password FROM users WHERE email=? LIMIT 1');$s->bind_param('s',$email);$s->execute();$u=$s->get_result()->fetch_assoc();if($u&&password_verify($pw,$u['password'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['user_name']=$u['name'];$_SESSION['user_email']=$u['email'];flash('success','Welcome back.');go('?p=dashboard');}$errors[]='Invalid email or password.';}
 if($a==='logout'){session_unset();session_destroy();go('?');}
 if(in_array($a,['save_car','delete_car'],true))guard();
 if($a==='delete_car'){$id=(int)($_POST['id']??0);$uid=(int)$_SESSION['user_id'];$s=$conn->prepare('DELETE FROM cars WHERE id=? AND user_id=?');$s->bind_param('ii',$id,$uid);$s->execute();flash('success','Car deleted successfully.');go('?p=collection');}
 if($a==='save_car'){$uid=(int)$_SESSION['user_id'];$id=(int)($_POST['id']??0);$name=trim($_POST['car_name']??'');$brand=trim($_POST['brand']??'');$model=trim($_POST['model']??'');$year=(int)($_POST['year']??0);$color=trim($_POST['color']??'');$fuel=$_POST['fuel_type']??'Petrol';$price=(float)($_POST['price']??0);$desc=trim($_POST['description']??'');$fuels=['Petrol','Diesel','Electric','Hybrid','CNG','Other'];if(!$name)$errors[]='Car name is required.';if(!$brand)$errors[]='Brand is required.';if(!$model)$errors[]='Model is required.';if($year<1900||$year>(int)date('Y')+1)$errors[]='Enter a valid year.';if(!$color)$errors[]='Colour is required.';if(!in_array($fuel,$fuels,true))$errors[]='Invalid fuel type.';if($price<0)$errors[]='Enter a valid price.';$imgData=null;$imgType=null;if(isset($_FILES['image'])&&$_FILES['image']['error']!==UPLOAD_ERR_NO_FILE){if($_FILES['image']['error']!==UPLOAD_ERR_OK)$errors[]='Image upload failed.';elseif($_FILES['image']['size']>1000000)$errors[]='Image must be smaller than 1MB.';else{$mime=mime_content_type($_FILES['image']['tmp_name']);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true))$errors[]='Only JPG, PNG and WEBP images are allowed.';else{$imgData=base64_encode(file_get_contents($_FILES['image']['tmp_name']));$imgType=$mime;}}}if(!$errors){if($id){$old=car($conn,$id,$uid);if(!$old){flash('error','Car not found.');go('?p=collection');}if($imgData!==null){$s=$conn->prepare('UPDATE cars SET car_name=?,brand=?,model=?,year=?,color=?,fuel_type=?,price=?,image_data=?,image_type=?,description=? WHERE id=? AND user_id=?');$s->bind_param('sssissdsssii',$name,$brand,$model,$year,$color,$fuel,$price,$imgData,$imgType,$desc,$id,$uid);}else{$s=$conn->prepare('UPDATE cars SET car_name=?,brand=?,model=?,year=?,color=?,fuel_type=?,price=?,description=? WHERE id=? AND user_id=?');$s->bind_param('sssissdsii',$name,$brand,$model,$year,$color,$fuel,$price,$desc,$id,$uid);}if($s->execute()){flash('success','Car updated successfully.');go('?p=view&id='.$id);}$errors[]='Could not update the car.';}else{$s=$conn->prepare('INSERT INTO cars(user_id,car_name,brand,model,year,color,fuel_type,price,image_data,image_type,description) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$s->bind_param('isssissdsss',$uid,$name,$brand,$model,$year,$color,$fuel,$price,$imgData,$imgType,$desc);if($s->execute()){flash('success','Car added successfully.');go('?p=collection');}$errors[]='Could not save the car.';}}}
}
if(in_array($p,['dashboard','collection','add','edit','view'],true))guard();
$flash=$_SESSION['flash']??null;unset($_SESSION['flash']);
$uid=(int)($_SESSION['user_id']??0);
$editCar=null;if(in_array($p,['edit','view'],true)){$editCar=car($conn,(int)($_GET['id']??0),$uid);if(!$editCar){flash('error','Car not found.');go('?p=collection');}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CarVault</title><style>
