on:column;justify-content:space-between}.carHero{font-size:112px;text-align:center}.section,.page{padding:54px 0}.features,.stats,.cars{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card,.stat{padding:20px}.card h3{margin:8px 0}.muted{color:var(--muted)}.stat span,.stat small{display:block;color:var(--muted)}.stat strong{display:block;font-size:30px;margin:7px 0}.pageHead{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:24px}.page h1{font-size:44px;margin-bottom:4px}.panel{padding:22px}.car{overflow:hidden;background:white;border:1px solid var(--line);border-radius:18px}.carImg{height:180px;background:linear-gradient(135deg,#eaf1fb,#dbe7f5);display:grid;place-items:center;font-size:64px}.carImg img{width:100%;height:100%;object-fit:cover}.carBody{padding:16px}.year{float:right;background:#eef2ff;color:#4338ca;border-radius:999px;padding:5px 8px;font-size:11px;font-weight:900}.price{font-size:18px;font-weight:900}.actions{display:flex;gap:8px;margin-top:14px}.actions a,.actions button{font-size:12px;font-weight:800;padding:8px 10px;border:0;border-radius:8px;background:#eef2ff;color:#4338ca;cursor:pointer}.actions .del{margin-left:auto;background:#fee2e2;color:#b91c1c}.filters{display:grid;grid-template-columns:2fr 1fr 1fr auto auto;gap:10px;margin-bottom:18px;background:#fff;border:1px solid var(--line);padding:14px;border-radius:16px}.filters input,.filters select,.field input,.field select,.field textarea{width:100%;padding:12px 13px;border:1px solid #d3dae6;border-radius:10px;background:#fff;outline:none}.filters input:focus,.filters select:focus,.field input:focus,.field select:focus,.field textarea:focus{border-color:#6b8ee9;box-shadow:0 0 0 4px rgba(37,99,235,.08)}.formGrid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.field{display:grid;gap:7px;font-size:13px;font-weight:800;color:#334155}.field.full{grid-column:1/-1}.field textarea{min-height:120px;resize:vertical}.authWrap{min-height:calc(100vh - 70px);display:grid;place-items:center;padding:50px 15px}.auth{width:min(480px,100%);padding:30px}.auth h1{font-size:34px;letter-spacing:-.04em}.alert{padding:13px 15px;border-radius:11px;margin:15px 0;font-weight:700}.alert.success{background:#ecfdf3;border:1px solid #abefc6;color:#067647}.alert.error{background:#fef3f2;border:1px solid #fecdca;color:#b42318}.detail{display:grid;grid-template-columns:1.05fr .95fr;gap:20px}.detailImg{height:440px;border-radius:15px;overflow:hidden;background:#e8edf5;display:grid;place-items:center;font-size:90px}.detailImg img{width:100%;height:100%;object-fit:cover}.specs{display:grid;grid-template-columns:1fr 1fr;gap:10px}.spec{border:1px solid var(--line);border-radius:11px;padding:12px}.footer{border-top:1px solid var(--line);background:#fff;padding:22px 0;color:var(--muted);font-size:12px;margin-top:30px}@media(max-width:900px){.heroGrid,.detail{grid-template-columns:1fr}.features,.stats,.cars{grid-template-columns:1fr 1fr}.filters{grid-template-columns:1fr 1fr}.filters .wide{grid-column:1/-1}}@media(max-width:650px){.nav>a:not(.brand){display:none}.features,.stats,.cars,.formGrid,.specs,.filters{grid-template-columns:1fr}.filters .wide,.field.full{grid-column:auto}.pageHead{align-items:flex-start;flex-direction:column}.hero h1{font-size:48px}.page h1{font-size:36px}.visual{min-height:280px}.carHero{font-size:90px}}
</style></head><body><header class="top"><div class="container nav"><a class="brand" href="?"><span class="logo">🚘</span>CarVault</a><?php if(logged()):?><a href="?p=dashboard">Dashboard</a><a href="?p=collection">My Collection</a><a href="?p=add">Add Car</a><form method="post" style="margin:0"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="logout"><button class="btn alt">Logout</button></form><?php else:?><a href="?p=login">Login</a><a class="btn blue" href="?p=register">Register</a><?php endif;?></div></header><main><?php if($flash):?><div class="container"><div class="alert <?=e($flash[0])?>"><?=e($flash[1])?></div></div><?php endif;?>
<?php if($p==='home'):?><section class="hero"><div class="container heroGrid"><div><div class="eyebrow">Your Personal Garage</div><h1>Manage your car collection in one clean place.</h1><p class="lead">Create an account, add cars, upload photos, search your collection, update vehicle details and keep everything organised.</p><div style="display:flex;gap:10px;margin-top:26px"><a class="btn blue" href="?p=register">Create Account</a><a class="btn alt" href="?p=login">Login</a></div></div><div class="visual"><div class="eyebrow" style="color:#93c5fd">CarVault</div><div class="carHero">🏎️</div><div>Private collections · Secure accounts · Search · Images · Full car management</div></div></div></section><section class="section"><div class="container"><div class="eyebrow">Core Features</div><h2 style="font-size:34px;letter-spacing:-.04em">Everything needed to organise your garage.</h2><div class="features"><div class="card"><b>01</b><h3>User Accounts</h3><p class="muted">Registration, secure passwords, login sessions and logout.</p></div><div class="card"><b>02</b><h3>Car Management</h3><p class="muted">Add, view, edit and delete cars from your own collection.</p></div><div class="card"><b>03</b><h3>Search & Filter</h3><p class="muted">Find cars by name, brand, model, year and fuel type.</p></div><div class="card"><b>04</b><h3>Image Uploads</h3><p class="muted">Save JPG, PNG or WEBP photos with each vehicle.</p></div></div></div></section>
