<?php elseif($p==='dashboard'):$s=$conn->prepare('SELECT COUNT(*) total,COALESCE(SUM(price),0) value,COUNT(DISTINCT brand) brands,COALESCE(AVG(year),0) avg_year FROM cars WHERE user_id=?');$s->bind_param('i',$uid);$s->execute();$st=$s->get_result()->fetch_assoc();$r=$conn->prepare('SELECT * FROM cars WHERE user_id=? ORDER BY created_at DESC LIMIT 4');$r->bind_param('i',$uid);$r->execute();$recent=$r->get_result();?><section class="page"><div class="container"><div class="pageHead"><div><div class="eyebrow">Dashboard</div><h1>Hello, <?=e($_SESSION['user_name'])?></h1><p class="muted">A quick overview of your collection.</p></div><a class="btn blue" href="?p=add">+ Add New Car</a></div><div class="stats"><div class="stat"><span>Total Cars</span><strong><?=(int)$st['total']?></strong><small>vehicles saved</small></div><div class="stat"><span>Collection Value</span><strong>₹<?=number_format((float)$st['value'],0)?></strong><small>entered prices</small></div><div class="stat"><span>Brands</span><strong><?=(int)$st['brands']?></strong><small>unique manufacturers</small></div><div class="stat"><span>Average Year</span><strong><?=(int)$st['total']?round($st['avg_year']):'—'?></strong><small>model year</small></div></div><div class="panel" style="margin-top:28px"><h2>Recently Added</h2><div class="cars"><?php while($c=$recent->fetch_assoc()):$src=imageSrc($c);?><div class="car"><div class="carImg"><?=$src?'<img src="'.$src.'" alt="'.e($c['car_name']).'">':'🚘'?></div><div class="carBody"><span class="year"><?=(int)$c['year']?></span><div class="muted" style="font-size:12px"><?=e($c['brand'])?> · <?=e($c['model'])?></div><h3><?=e($c['car_name'])?></h3><div class="price">₹<?=number_format((float)$c['price'],0)?></div><div class="actions"><a href="?p=view&id=<?=(int)$c['id']?>">View</a><a href="?p=edit&id=<?=(int)$c['id']?>">Edit</a></div></div></div><?php endwhile;?></div></div></div></section>
<?php elseif($p==='collection'):$search=trim($_GET['search']??'');$fuel=trim($_GET['fuel']??'');$year=trim($_GET['year']??'');$sql='SELECT * FROM cars WHERE user_id=?';$types='i';$params=[$uid];if($search!==''){$sql.=' AND (car_name LIKE ? OR brand LIKE ? OR model LIKE ? OR color LIKE ?)';$like='%'.$search.'%';$types.='ssss';array_push($params,$like,$like,$like,$like);}if($fuel!==''){$sql.=' AND fuel_type=?';$types.='s';$params[]=$fuel;}if($year!==''&&ctype_digit($year)){$sql.=' AND year=?';$types.='i';$params[]=(int)$year;}$sql.=' ORDER BY created_at DESC';$s=$conn->prepare($sql);$s->bind_param($types,...$params);$s->execute();$cars=$s->get_result();?><section class="page"><div class="container"><div class="pageHead"><div><div class="eyebrow">Collection</div><h1>My Cars</h1><p class="muted">Search, filter and manage every vehicle.</p></div><a class="btn blue" href="?p=add">+ Add Car</a></div><form class="filters"><input type="hidden" name="p" value="collection"><input class="wide" name="search" value="<?=e($search)?>" placeholder="Search car, brand, model or colour"><select name="fuel"><option value="">All fuel types</option><?php foreach(['Petrol','Diesel','Electric','Hybrid','CNG','Other'] as $f):?><option <?=$fuel===$f?'selected':''?>><?=$f?></option><?php endforeach;?></select><input name="year" value="<?=e($year)?>" placeholder="Year"><button class="btn blue">Filter</button><a class="btn alt" href="?p=collection">Reset</a></form><div class="cars"><?php while($c=$cars->fetch_assoc()):$src=imageSrc($c);?><div class="car"><div class="carImg"><?=$src?'<img src="'.$src.'" alt="'.e($c['car_name']).'">':'🚘'?></div><div class="carBody"><span class="year"><?=(int)$c['year']?></span><div class="muted" style="font-size:12px"><?=e($c['brand'])?> · <?=e($c['model'])?></div><h3><?=e($c['car_name'])?></h3><div class="muted"><?=e($c['fuel_type'])?> · <?=e($c['color'])?></div><div class="price">₹<?=number_format((float)$c['price'],0)?></div><div class="actions"><a href="?p=view&id=<?=(int)$c['id']?>">View</a><a href="?p=edit&id=<?=(int)$c['id']?>">Edit</a><form method="post" style="margin-left:auto"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="delete_car"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><button class="del" data-confirm>Delete</button></form></div></div></div><?php endwhile;?></div></div></section>
<?php elseif($p==='add'||$p==='edit'):$c=$editCar?:['id'=>0,'car_name'=>'','brand'=>'','model'=>'','year'=>'','color'=>'','fuel_type'=>'Petrol','price'=>'','description'=>''];?><section class="page"><div class="container" style="max-width:900px"><div class="pageHead"><div><div class="eyebrow"><?=$p==='edit'?'Update Entry':'New Entry'?></div><h1><?=$p==='edit'?'Edit Car':'Add a Car'?></h1><p class="muted">Enter the vehicle details below.</p></div><a class="btn alt" href="?p=collection">← Back</a></div><?php foreach($errors as $x):?><div class="alert error"><?=e($x)?></div><?php endforeach;?><div class="panel"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="save_car"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><div class="formGrid"><label class="field">Car Name *<input name="car_name" required value="<?=e($c['car_name'])?>"></label><label class="field">Brand *<input name="brand" required value="<?=e($c['brand'])?>"></label><label class="field">Model *<input name="model" required value="<?=e($c['model'])?>"></label><label class="field">Year *<input type="number" name="year" min="1900" max="<?=date('Y')+1?>" required value="<?=e($c['year'])?>"></label><label class="field">Colour *<input name="color" required value="<?=e($c['color'])?>"></label><label class="field">Fuel Type *<select name="fuel_type"><?php foreach(['Petrol','Diesel','Electric','Hybrid','CNG','Other'] as $f):?><option <?=$c['fuel_type']===$f?'selected':''?>><?=$f?></option><?php endforeach;?></select></label><label class="field">Price (₹) *<input type="number" name="price" min="0" step="0.01" required value="<?=e($c['price'])?>"></label><label class="field">Car Image<input type="file" name="image" accept="image/jpeg,image/png,image/webp"><small class="muted">JPG, PNG or WEBP · max 1MB</small></label><label class="field full">Notes<textarea name="description"><?=e($c['description'])?></textarea></label></div><div style="margin-top:18px"><button class="btn blue"><?=$p==='edit'?'Update Car':'Save Car'?></button></div></form></div></div></section>
<?php elseif($p==='view'):$c=$editCar;$src=imageSrc($c);?><section class="page"><div class="container"><a href="?p=collection" style="font-weight:800;color:#4f46e5">← Back to collection</a><div class="detail" style="margin-top:18px"><div class="panel"><div class="detailImg"><?=$src?'<img src="'.$src.'" alt="'.e($c['car_name']).'">':'🚘'?></div></div><div class="panel"><div class="eyebrow"><?=e($c['brand'])?></div><h1 style="font-size:42px"><?=e($c['car_name'])?></h1><p class="muted"><?=e($c['model'])?> · <?=(int)$c['year']?></p><div class="price" style="font-size:30px;margin:20px 0">₹<?=number_format((float)$c['price'],0)?></div><div class="specs"><div class="spec"><span class="muted">Brand</span><br><b><?=e($c['brand'])?></b></div><div class="spec"><span class="muted">Model</span><br><b><?=e($c['model'])?></b></div><div class="spec"><span class="muted">Fuel</span><br><b><?=e($c['fuel_type'])?></b></div><div class="spec"><span class="muted">Colour</span><br><b><?=e($c['color'])?></b></div></div><?php if($c['description']):?><div class="card" style="margin-top:14px"><b>Notes</b><p class="muted"><?=nl2br(e($c['description']))?></p></div><?php endif;?><div class="actions"><a href="?p=edit&id=<?=(int)$c['id']?>">Edit Car</a><form method="post" style="margin-left:auto"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="delete_car"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><button class="del" data-confirm>Delete Car</button></form></div></div></div></div></section><?php endif;?></main><footer class="footer"><div class="container">CarVault · Car Collection Management System</div></footer><script>document.querySelectorAll('[data-confirm]').forEach(b=>b.addEventListener('click',e=>{if(!confirm('Delete this car? This action cannot be undone.'))e.preventDefault()}));</script></body></html>